SELECT analytics_order_facts.category, SUM(analytics_order_facts.net_revenue) AS net_revenue FROM analytics_order_facts WHERE analytics_order_facts.year = 2024 AND analytics_order_facts.month = 11 AND analytics_order_facts.region = 'East' AND analytics_order_facts.channel = 'retail' AND analytics_order_facts.customer_segment = 'mid_market' AND analytics_order_facts.category = 'category_05' GROUP BY analytics_order_facts.category ORDER BY net_revenue DESC, analytics_order_facts.category ASC LIMIT 10
